/* New translated stories: 18 level 1, 18 level 2, 14 level 3 (tag: חדש) */
const NEW_STORIES = [
 { id:"n1_morning_train", level:1, cover:"🚆", title:"The Morning Train", he:"רכבת הבוקר", blurb:"בוקר רגיל אחד בדרך לעבודה ברכבת.", paras:[
  { en:"David wakes up at six o'clock every morning. He washes his face and eats a quick breakfast of bread and cheese. At seven o'clock, he walks to the train station near his house.", he:"דוד מתעורר כל בוקר בשעה שש. הוא שוטף את הפנים ואוכל ארוחת בוקר מהירה של לחם וגבינה. בשעה שבע הוא הולך לתחנת הרכבת ליד הבית שלו." },
  { en:"The station is always busy with people going to work. David buys a ticket and waits on the platform. When the blue train arrives, he finds a quiet seat by the window.", he:"התחנה תמיד עמוסה באנשים שנוסעים לעבודה. דוד קונה כרטיס ומחכה על הרציף. כשהרכבת הכחולה מגיעה, הוא מוצא מקום שקט ליד החלון." },
  { en:"During the ride, he reads a book and looks at the green fields outside. Thirty minutes later, he arrives in the city and walks to his office.", he:"במהלך הנסיעה הוא קורא ספר ומסתכל על השדות הירוקים בחוץ. שלושים דקות אחר כך הוא מגיע לעיר והולך למשרד שלו." } ]},
 { id:"n1_bakery", level:1, cover:"🥐", title:"A Visit to the Bakery", he:"ביקור במאפייה", blurb:"ריח של לחם טרי מחכה ברחוב הראשי.", paras:[
  { en:"Sarah loves the smell of fresh bread in the morning. Every Friday, she walks to the small bakery on Main Street. The baker, Mr. Green, always greets her with a warm smile.", he:"שרה אוהבת את הריח של לחם טרי בבוקר. בכל יום שישי היא הולכת למאפייה הקטנה ברחוב הראשי. האופה, מר גרין, תמיד מקבל אותה בחיוך חם." },
  { en:"Today, Sarah wants to buy two loaves of brown bread and four sweet rolls. She looks at the shelves full of golden pastries and cakes. Mr. Green puts the warm bread into a brown paper bag.", he:"היום שרה רוצה לקנות שתי כיכרות לחם חום וארבע לחמניות מתוקות. היא מסתכלת על המדפים המלאים במאפים ובעוגות זהובים. מר גרין שם את הלחם החם בשקית נייר חומה." },
  { en:"Sarah pays for her items and thanks him. She walks home happily with the warm bag in her hands.", he:"שרה משלמת על מה שקנתה ומודה לו. היא הולכת הביתה בשמחה עם השקית החמה בידיים." } ]},
 { id:"n1_small_garden", level:1, cover:"🌱", title:"Planting a Small Garden", he:"שותלים גינה קטנה", blurb:"כמה זרעים קטנים, קצת מים והרבה סבלנות.", paras:[
  { en:"Tom has a small backyard behind his house. This spring, he decides to plant a vegetable garden.", he:"לתום יש חצר קטנה מאחורי הבית שלו. באביב הזה הוא מחליט לשתול גינת ירקות." },
  { en:"First, he buys seeds for tomatoes, carrots, and cucumbers from a local shop. On Sunday morning, he clears the dry leaves and digs the soft soil. He carefully places the tiny seeds in neat rows and covers them with dirt.", he:"קודם הוא קונה זרעים של עגבניות, גזר ומלפפונים בחנות מקומית. ביום ראשון בבוקר הוא מנקה את העלים היבשים וחופר באדמה הרכה. הוא מניח בזהירות את הזרעים הקטנטנים בשורות מסודרות ומכסה אותם באדמה." },
  { en:"Every evening after work, Tom waters the garden with a green watering can. After a few weeks, small green leaves begin to grow toward the warm sun.", he:"כל ערב אחרי העבודה תום משקה את הגינה עם משפך ירוק. אחרי כמה שבועות, עלים ירוקים קטנים מתחילים לצמוח לכיוון השמש החמה." } ]},
 { id:"n1_lost_umbrella", level:1, cover:"☂️", title:"The Lost Umbrella", he:"המטרייה האבודה", blurb:"יום גשום בלונדון ומשהו חשוב נשכח.", paras:[
  { en:"It is a rainy Tuesday afternoon in London. Michael finishes his work at the library and walks to the bus stop. When the rain stops, he gets on the bus and sits down.", he:"זה אחר צהריים גשום של יום שלישי בלונדון. מייקל מסיים את העבודה שלו בספרייה והולך לתחנת האוטובוס. כשהגשם נפסק, הוא עולה על האוטובוס ומתיישב." },
  { en:"After ten minutes, he looks at his hands and realizes his black umbrella is missing. He left it on the bench at the bus stop.", he:"אחרי עשר דקות הוא מסתכל על הידיים שלו ומבין שהמטרייה השחורה שלו חסרה. הוא שכח אותה על הספסל בתחנת האוטובוס." },
  { en:"The next morning, Michael walks back to the same stop early. To his surprise, the umbrella is still leaning against the bench. He picks it up and smiles.", he:"למחרת בבוקר מייקל הולך מוקדם חזרה לאותה תחנה. להפתעתו, המטרייה עדיין נשענת על הספסל. הוא מרים אותה ומחייך." } ]},
 { id:"n1_vegetable_soup", level:1, cover:"🍲", title:"Learning to Cook Soup", he:"לומדים לבשל מרק", blurb:"ערב קר, סיר גדול וארוחה חמה למשפחה.", paras:[
  { en:"Rachel wants to make a warm dinner for her family on a cold evening. She decides to cook a simple vegetable soup.", he:"רחל רוצה להכין ארוחת ערב חמה למשפחה שלה בערב קר. היא מחליטה לבשל מרק ירקות פשוט." },
  { en:"She takes a large pot and fills it with clean water. Next, she washes and cuts potatoes, carrots, onions, and celery into small pieces. She puts all the vegetables into the pot and adds a little salt and pepper.", he:"היא לוקחת סיר גדול וממלאת אותו במים נקיים. אחר כך היא שוטפת וחותכת תפוחי אדמה, גזר, בצל וסלרי לחתיכות קטנות. היא שמה את כל הירקות בסיר ומוסיפה קצת מלח ופלפל." },
  { en:"The soup cooks slowly on the stove for one hour. Soon, the whole kitchen smells wonderful, and everyone enjoys a hot bowl of soup.", he:"המרק מתבשל לאט על הכיריים במשך שעה אחת. עד מהרה כל המטבח מריח נפלא, וכולם נהנים מקערת מרק חם." } ]},
 { id:"n1_library_day", level:1, cover:"📚", title:"A Day at the Library", he:"יום בספרייה", blurb:"מקום שקט, מדפים גבוהים ואלפי ספרים.", paras:[
  { en:"The city library is a very quiet and peaceful place. Every Wednesday afternoon, Daniel goes there to study and read. He walks past the tall shelves filled with thousands of books about history, science, and nature.", he:"הספרייה העירונית היא מקום שקט ורגוע מאוד. בכל יום רביעי אחר הצהריים דניאל הולך לשם ללמוד ולקרוא. הוא עובר ליד המדפים הגבוהים המלאים באלפי ספרים על היסטוריה, מדע וטבע." },
  { en:"Daniel chooses two books about famous explorers and sits at a wooden table near the window. Sunlight shines through the glass while he takes notes in his notebook. He stays for two hours until the library closes at six o'clock in the evening.", he:"דניאל בוחר שני ספרים על חוקרים מפורסמים ומתיישב ליד שולחן עץ ליד החלון. אור השמש נכנס דרך הזכוכית בזמן שהוא כותב הערות במחברת שלו. הוא נשאר שעתיים, עד שהספרייה נסגרת בשש בערב." } ]},
 { id:"n1_new_shoes", level:1, cover:"👟", title:"Buying New Shoes", he:"קונים נעליים חדשות", blurb:"הנעליים הישנות נשחקו, והגיע הזמן לזוג חדש.", paras:[
  { en:"Sam needs a new pair of walking shoes because his old ones are worn out. On Monday afternoon, he visits a large shoe store in the shopping center. A helpful clerk measures Sam's feet and brings out three different boxes.", he:"סם צריך זוג חדש של נעלי הליכה, כי הישנות שלו שחוקות. ביום שני אחר הצהריים הוא מבקר בחנות נעליים גדולה במרכז הקניות. מוכר נחמד מודד את כפות הרגליים של סם ומביא שלוש קופסאות שונות." },
  { en:"Sam tries on a pair of dark blue shoes first. They feel very comfortable and light. He walks around the store for a minute to test them. Satisfied with the fit, Sam pays at the counter and wears his new shoes home.", he:"סם מודד קודם זוג נעליים בצבע כחול כהה. הן מרגישות נוחות וקלות מאוד. הוא מסתובב בחנות דקה אחת כדי לבדוק אותן. מרוצה מהמידה, סם משלם בקופה והולך הביתה עם הנעליים החדשות שלו." } ]},
 { id:"n1_mountain_walk", level:1, cover:"⛰️", title:"The Mountain Walk", he:"טיול בהרים", blurb:"שני אחים, תרמילים ושביל שעולה למעלה.", paras:[
  { en:"Last summer, Joseph went on a trip to the mountains with his brother. Early in the morning, they packed water bottles, apples, and sandwiches into their backpacks. They followed a wide dirt path that went up a tall green hill.", he:"בקיץ שעבר יוסף יצא לטיול בהרים עם אחיו. מוקדם בבוקר הם ארזו בקבוקי מים, תפוחים וכריכים בתרמילים שלהם. הם הלכו בשביל עפר רחב שעלה על גבעה ירוקה וגבוהה." },
  { en:"Along the way, they saw tall pine trees and colorful wildflowers. Birds sang high in the branches above them. When they reached the top, they rested on a flat rock and looked at the beautiful valley far below.", he:"בדרך הם ראו עצי אורן גבוהים ופרחי בר צבעוניים. ציפורים שרו גבוה בענפים מעליהם. כשהם הגיעו לפסגה, הם נחו על סלע שטוח והסתכלו על העמק היפה הרחק למטה." } ]},
 { id:"n1_bicycle_fix", level:1, cover:"🚲", title:"Fixing the Bicycle", he:"מתקנים את האופניים", blurb:"צמיג שטוח וארגז כלים אחד.", paras:[
  { en:"Ben likes to ride his bicycle in the park every afternoon. Yesterday, he noticed that the front tire was completely flat. Instead of taking it to a shop, Ben decided to fix it himself.", he:"בן אוהב לרכוב על האופניים שלו בפארק כל אחר צהריים. אתמול הוא שם לב שהצמיג הקדמי היה שטוח לגמרי. במקום לקחת אותם לחנות, בן החליט לתקן אותם בעצמו." },
  { en:"He took out his toolbox and turned the bicycle upside down on the grass. He carefully removed the rubber tube, found a tiny hole, and put a strong patch over it. After pumping fresh air into the tire, the bicycle was ready to ride again.", he:"הוא הוציא את ארגז הכלים שלו והפך את האופניים על הדשא. הוא הוציא בזהירות את הפנימית מגומי, מצא חור קטנטן ושם עליו טלאי חזק. אחרי שהוא ניפח אוויר חדש לתוך הצמיג, האופניים היו מוכנים לרכיבה שוב." } ]},
 { id:"n1_cup_of_tea", level:1, cover:"🍵", title:"A Cup of Tea", he:"כוס תה", blurb:"הפסקה קטנה ושקטה באמצע היום.", paras:[
  { en:"In the late afternoon, Mrs. Miller always takes a short break from her work. She fills a silver kettle with cold water and puts it on the stove.", he:"בשעות אחר הצהריים המאוחרות, גברת מילר תמיד לוקחת הפסקה קצרה מהעבודה שלה. היא ממלאת קומקום כסוף במים קרים ושמה אותו על הכיריים." },
  { en:"While the water heats up, she takes a white cup and a small teapot from the cupboard. When the water boils, she pours it over the dry tea leaves in the pot. After waiting three minutes, she pours the warm amber tea into her cup and sits comfortably in her armchair.", he:"בזמן שהמים מתחממים, היא מוציאה כוס לבנה וקנקן תה קטן מהארון. כשהמים רותחים, היא שופכת אותם על עלי התה היבשים שבקנקן. אחרי שהיא מחכה שלוש דקות, היא מוזגת את התה החם בצבע ענבר לכוס שלה ויושבת בנוחות בכורסה שלה." } ]},
 { id:"n1_post_office", level:1, cover:"📦", title:"The Post Office", he:"בדואר", blurb:"חבילת יום הולדת יוצאת לדרך.", paras:[
  { en:"Anna needs to send a birthday package to her cousin who lives in another city. She puts a new book and a handwritten card inside a sturdy cardboard box. She seals the box with strong tape and writes the address clearly on the front.", he:"אנה צריכה לשלוח חבילת יום הולדת לבת הדודה שלה, שגרה בעיר אחרת. היא שמה ספר חדש וכרטיס בכתב יד בתוך קופסת קרטון חזקה. היא סוגרת את הקופסה בסלוטייפ חזק וכותבת את הכתובת בבירור על הצד הקדמי." },
  { en:"Then, she walks two blocks to the local post office. There is a short line at the counter. When it is her turn, the clerk weighs the box, puts a stamp on it, and gives Anna a receipt.", he:"אחר כך היא הולכת שני רחובות לסניף הדואר המקומי. יש תור קצר ליד הדלפק. כשמגיע תורה, הפקיד שוקל את הקופסה, מדביק עליה בול ונותן לאנה קבלה." } ]},
 { id:"n1_fruit_market", level:1, cover:"🍎", title:"The Fruit Market", he:"שוק הפירות", blurb:"דוכנים צבעוניים וסל גדול בכיכר העיר.", paras:[
  { en:"Every Tuesday morning, a lively outdoor market opens in the town square. Farmers from nearby villages bring fresh fruits and vegetables in wooden crates. Miriam walks between the colorful stalls with a large woven basket.", he:"בכל יום שלישי בבוקר נפתח שוק פתוח ותוסס בכיכר העיר. חקלאים מכפרים קרובים מביאים פירות וירקות טריים בארגזי עץ. מרים הולכת בין הדוכנים הצבעוניים עם סל קלוע גדול." },
  { en:"She buys red apples, sweet oranges, yellow bananas, and fresh green spinach. The prices are fair, and the food is very fresh. Miriam chats briefly with the farmers before walking back home with her heavy basket.", he:"היא קונה תפוחים אדומים, תפוזים מתוקים, בננות צהובות ותרד ירוק וטרי. המחירים הוגנים, והאוכל טרי מאוד. מרים משוחחת קצת עם החקלאים לפני שהיא חוזרת הביתה עם הסל הכבד שלה." } ]},
 { id:"n1_clean_study", level:1, cover:"🧹", title:"Cleaning the Study", he:"מסדרים את חדר העבודה", blurb:"שולחן מבולגן ואחר צהריים אחד של סדר.", paras:[
  { en:"Mark's desk was covered with old papers, notebooks, and pens. On Sunday afternoon, he decided it was time to organize his study.", he:"השולחן של מארק היה מכוסה בניירות ישנים, מחברות ועטים. ביום ראשון אחר הצהריים הוא החליט שהגיע הזמן לסדר את חדר העבודה שלו." },
  { en:"First, he threw away old receipts and papers he no longer needed. Next, he stacked his notebooks neatly on the bookshelf and put all his pens into a ceramic cup.", he:"קודם הוא זרק קבלות ישנות וניירות שהוא כבר לא היה צריך. אחר כך הוא סידר את המחברות שלו בערימה מסודרת על מדף הספרים ושם את כל העטים שלו בכוס קרמיקה." },
  { en:"Finally, he wiped the wooden desk with a clean cloth. When he finished, the room looked bright, tidy, and ready for a new week of work.", he:"לבסוף הוא ניגב את שולחן העץ במטלית נקייה. כשהוא סיים, החדר נראה מואר, מסודר ומוכן לשבוע חדש של עבודה." } ]},
 { id:"n1_clockmaker", level:1, cover:"🕰️", title:"The Clockmaker's Shop", he:"החנות של השען", blurb:"חנות קטנה שמלאה בתקתוק של שעונים.", paras:[
  { en:"On a quiet corner of Old Street, there is a tiny shop full of clocks. Mr. Brown, the clockmaker, repairs old wall clocks and pocket watches. Inside the shop, you can hear the soft ticking sound of dozens of clocks working together.", he:"בפינה שקטה של הרחוב העתיק יש חנות קטנטנה מלאה בשעונים. מר בראון, השען, מתקן שעוני קיר ישנים ושעוני כיס. בתוך החנות אפשר לשמוע את התקתוק השקט של עשרות שעונים שעובדים יחד." },
  { en:"Yesterday, David brought his grandfather's old wooden clock to the shop because it had stopped running. Mr. Brown looked inside with a small magnifying glass, oiled the tiny gears, and made it tick again.", he:"אתמול דוד הביא לחנות את שעון העץ הישן של סבא שלו, כי הוא הפסיק לעבוד. מר בראון הסתכל פנימה עם זכוכית מגדלת קטנה, שימן את גלגלי השיניים הקטנטנים וגרם לו לתקתק שוב." } ]},
 { id:"n1_rainy_day", level:1, cover:"🧩", title:"A Rainy Day Indoors", he:"יום גשום בבית", blurb:"גשם בחוץ, ופאזל גדול בפנים.", paras:[
  { en:"Heavy rain poured from the gray clouds all Saturday afternoon. Because they could not play outside, Leo and his younger brother stayed indoors.", he:"גשם כבד ירד מהעננים האפורים כל אחר הצהריים של שבת. מפני שהם לא יכלו לשחק בחוץ, ליאו ואחיו הצעיר נשארו בבית." },
  { en:"They cleared the living room table and opened a large box containing a thousand-piece puzzle. The picture showed a peaceful village beside a blue lake.", he:"הם פינו את השולחן בסלון ופתחו קופסה גדולה עם פאזל של אלף חלקים. התמונה הראתה כפר שקט ליד אגם כחול." },
  { en:"They started by finding all the flat edge pieces first. While rain tapped against the window, they worked together patiently for hours.", he:"הם התחילו בכך שמצאו קודם את כל חלקי השוליים הישרים. בזמן שהגשם תופף על החלון, הם עבדו יחד בסבלנות במשך שעות." } ]},
 { id:"n1_night_sky", level:1, cover:"🌌", title:"The Night Sky", he:"שמי הלילה", blurb:"רחוק מאורות העיר, השמיים נראים אחרת.", paras:[
  { en:"Far away from the bright lights of the city, the night sky looks very different. Last night, Adam and his father drove out to a quiet hill in the countryside. They brought a folding chair and a pair of binoculars.", he:"רחוק מהאורות הבהירים של העיר, שמי הלילה נראים שונים מאוד. אתמול בלילה אדם ואבא שלו נסעו לגבעה שקטה באזור כפרי. הם הביאו כיסא מתקפל ומשקפת." },
  { en:"Looking up, they saw thousands of bright stars shining in the dark sky. Adam's father pointed out several famous star patterns and explained how travelers used them to find their way long ago.", he:"כשהם הסתכלו למעלה, הם ראו אלפי כוכבים בהירים זורחים בשמיים החשוכים. אבא של אדם הראה כמה קבוצות כוכבים מפורסמות והסביר איך מטיילים השתמשו בהן כדי למצוא את הדרך לפני הרבה זמן." } ]},
 { id:"n1_baking_bread", level:1, cover:"🍞", title:"Baking Bread", he:"אופים לחם", blurb:"קמח, מים, שמרים והרבה סבלנות.", paras:[
  { en:"Making bread at home takes time, but the result is delicious. Early in the morning, Hannah mixes flour, warm water, yeast, and a pinch of salt in a large bowl.", he:"להכין לחם בבית לוקח זמן, אבל התוצאה טעימה. מוקדם בבוקר חנה מערבבת קמח, מים חמימים, שמרים וקורט מלח בקערה גדולה." },
  { en:"She kneads the soft dough on the kitchen counter for ten minutes until it becomes smooth. Then, she covers the bowl with a clean towel and lets the dough rise for two hours. Finally, she bakes it in a hot oven until the crust turns golden brown.", he:"היא לשה את הבצק הרך על משטח המטבח במשך עשר דקות, עד שהוא נעשה חלק. אחר כך היא מכסה את הקערה במגבת נקייה ונותנת לבצק לתפוח במשך שעתיים. לבסוף היא אופה אותו בתנור חם עד שהקרום נעשה חום זהוב." } ]},
 { id:"n1_new_notebook", level:1, cover:"📓", title:"The New Notebook", he:"המחברת החדשה", blurb:"לפני כל שנת לימודים יש פריט אחד מיוחד.", paras:[
  { en:"Every year before school starts, Jacob buys new supplies. His favorite item is always a thick, lined notebook with a dark green cover.", he:"בכל שנה, לפני שהלימודים מתחילים, יעקב קונה ציוד חדש. הפריט האהוב עליו הוא תמיד מחברת עבה עם שורות וכריכה ירוקה כהה." },
  { en:"On the first page, he writes his name, the date, and his goals for the year in neat handwriting. He uses the notebook to write down new English words he learns every day. Watching the blank pages slowly fill up with knowledge gives Jacob a great sense of pride.", he:"בעמוד הראשון הוא כותב את השם שלו, את התאריך ואת המטרות שלו לשנה, בכתב יד מסודר. הוא משתמש במחברת כדי לכתוב מילים חדשות באנגלית שהוא לומד כל יום. לראות את הדפים הריקים מתמלאים לאט בידע נותן ליעקב תחושת גאווה גדולה." } ]},
 { id:"n2_watchmaking", level:2, cover:"⌚", title:"The Art of Watchmaking", he:"אומנות השענות", blurb:"מסע אל עולם הגלגלים הזעירים של שען בהרי שווייץ.", paras:[
  { en:"In a small town nestled in the Swiss mountains, watchmaking is more than just a profession; it is a respected tradition passed down through generations. Henry works in a bright studio overlooking the valley, where precision is everything.", he:"בעיירה קטנה השוכנת בהרי שווייץ, ייצור שעונים הוא יותר מסתם מקצוע; זו מסורת מכובדת שעוברת מדור לדור. הנרי עובד בסטודיו מואר המשקיף אל העמק, ושם הדיוק הוא הכול." },
  { en:"Every morning, he puts on his magnifying loupe and examines microscopic gears made of brass and steel. A single mechanical watch can contain over two hundred tiny parts that must fit together without the slightest error. If one spring is slightly out of place, the watch will lose seconds every day.", he:"בכל בוקר הוא מרכיב את זכוכית המגדלת שלו ובוחן גלגלי שיניים זעירים העשויים פליז ופלדה. שעון מכני אחד יכול להכיל יותר ממאתיים חלקים קטנטנים, שחייבים להתאים זה לזה בלי הטעות הקלה ביותר. אם קפיץ אחד זז ממקומו ולו במעט, השעון יאבד שניות בכל יום." },
  { en:"Henry spends weeks assembling and testing each timepiece carefully. When he finally hears the steady, rhythmic heartbeat of a completed watch, he knows his patience has created something built to last a century.", he:"הנרי מקדיש שבועות להרכבה ולבדיקה קפדנית של כל שעון. כשהוא שומע סוף סוף את פעימות הלב הקבועות והקצובות של שעון גמור, הוא יודע שהסבלנות שלו יצרה משהו שנבנה להחזיק מעמד מאה שנה." } ]},
 { id:"n2_detour", level:2, cover:"🚗", title:"The Unexpected Detour", he:"המעקף הלא צפוי", blurb:"תוכנית נסיעה פשוטה משתנה בגלל כביש סגור.", paras:[
  { en:"Jonathan planned to drive straight from his hometown to a business conference in the north, a journey that normally took three hours on the main highway. However, halfway through the trip, heavy road construction forced all traffic onto a narrow country road.", he:"יונתן תכנן לנסוע ישירות מעיר הולדתו לכנס עסקי בצפון, נסיעה שבדרך כלל נמשכה שלוש שעות בכביש הראשי. אבל באמצע הדרך, עבודות כביש גדולות הסיטו את כל התנועה לכביש כפרי צר." },
  { en:"At first, Jonathan felt frustrated because he worried about arriving late. Yet, as he drove slowly through the winding route, his mood began to change.", he:"בהתחלה יונתן היה מתוסכל, כי חשש שיאחר. אבל בזמן שנסע לאט בדרך המתפתלת, מצב רוחו התחיל להשתנות." },
  { en:"The detour took him past rolling green hills, stone bridges, and quiet orchards filled with blooming apple trees. He stopped briefly at a roadside stand to buy fresh cider and enjoy the crisp country air. Although he arrived at the conference twenty minutes later than expected, the peaceful scenery had completely refreshed his mind.", he:"המעקף הוביל אותו על פני גבעות ירוקות ומתגלגלות, גשרי אבן ומטעים שקטים מלאים בעצי תפוח פורחים. הוא עצר לרגע בדוכן לצד הדרך כדי לקנות סיידר טרי וליהנות מאוויר הכפר הצלול. אף שהגיע לכנס עשרים דקות מאוחר מהצפוי, הנוף השליו רענן לגמרי את מחשבתו." } ]},
 { id:"n2_bookshelf", level:2, cover:"📚", title:"Building a Wooden Bookshelf", he:"בונים כוננית עץ", blurb:"כשהמדף מתמלא, מרים מחליטה לקחת את העבודה לידיים.", paras:[
  { en:"After collecting books for several years, Miriam realized her small shelf could no longer hold them all. Instead of buying a factory-made unit, she decided to build a custom wooden bookshelf herself. She visited a local lumberyard, selected sturdy planks of oak, and had them cut to the exact measurements of her living room wall.", he:"אחרי שאספה ספרים במשך כמה שנים, מרים הבינה שהמדף הקטן שלה כבר לא יכול להכיל את כולם. במקום לקנות רהיט מתוצרת מפעל, היא החליטה לבנות בעצמה כוננית עץ בהתאמה אישית. היא ביקרה במחסן עצים מקומי, בחרה קרשים חזקים מעץ אלון, וביקשה לחתוך אותם לפי המידות המדויקות של קיר הסלון שלה." },
  { en:"Over the weekend, she sanded each board until the surface felt completely smooth. Using a drill, wood glue, and brass screws, she carefully assembled the frame, checking constantly with a level to ensure the shelves were straight.", he:"במהלך סוף השבוע היא שייפה כל קרש עד שהמשטח היה חלק לגמרי. בעזרת מקדחה, דבק עץ וברגי פליז, היא הרכיבה בזהירות את המסגרת, ובדקה כל הזמן עם פלס כדי לוודא שהמדפים ישרים." },
  { en:"Finally, she applied a coat of natural beeswax to bring out the warm grain of the wood. Standing back to admire her work, she felt proud of creating something both useful and durable.", he:"לבסוף היא מרחה שכבה של שעוות דבורים טבעית כדי להבליט את הסיבים החמימים של העץ. כשעמדה מאחור והתפעלה מעבודתה, היא הרגישה גאה שיצרה משהו שימושי ועמיד כאחד." } ]},
 { id:"n2_lighthouse", level:2, cover:"🌊", title:"The Lighthouse Keeper's Routine", he:"השגרה של שומר המגדלור", blurb:"ערב אחד בחייו של האיש ששומר על האור מעל הים.", paras:[
  { en:"Standing on a rocky cliff above the Atlantic Ocean, the old stone lighthouse has guided ships safely away from dangerous reefs for over a hundred years. Thomas is responsible for maintaining the beacon and weather station.", he:"על צוק סלעי מעל האוקיינוס האטלנטי ניצב מגדלור האבן הישן, שכבר יותר ממאה שנה מנחה ספינות בבטחה הרחק משוניות מסוכנות. תומאס אחראי על תחזוקת המשואה ותחנת מזג האוויר." },
  { en:"Every evening before sunset, he climbs the spiral iron staircase to the lantern room at the top. He cleans the large glass lenses so the beam of light shines clearly across twenty miles of dark water.", he:"בכל ערב לפני השקיעה הוא מטפס במדרגות הברזל הלולייניות אל חדר הפנס שבראש המגדל. הוא מנקה את עדשות הזכוכית הגדולות, כדי שאלומת האור תאיר בבהירות למרחק עשרים מייל של מים חשוכים." },
  { en:"Throughout the night, Thomas records wind speeds, temperature changes, and sea conditions in a thick logbook. Even though modern ships use satellite navigation today, sailors still appreciate seeing the steady, reliable flash of the lighthouse cutting through thick coastal fog.", he:"לאורך כל הלילה תומאס רושם ביומן עבה את מהירויות הרוח, שינויי הטמפרטורה ומצב הים. אף שספינות מודרניות משתמשות היום בניווט לוויני, מלחים עדיין שמחים לראות את ההבזק הקבוע והאמין של המגדלור חותך את הערפל הסמיך שליד החוף." } ]},
 { id:"n2_patience", level:2, cover:"🎻", title:"A Lesson in Patience", he:"שיעור בסבלנות", blurb:"דניאל מגלה שכינור לא נכבש בשבוע אחד.", paras:[
  { en:"When Daniel first started learning to play the violin, he expected to play beautiful melodies within a few weeks. Instead, his initial attempts produced scratchy, uneven sounds that tested his determination. His teacher, Mr. Klein, explained that mastering a string instrument requires building muscle memory slowly.", he:"כשדניאל התחיל ללמוד לנגן בכינור, הוא ציפה לנגן מנגינות יפות בתוך כמה שבועות. במקום זה, הניסיונות הראשונים שלו הפיקו צלילים צורמים ולא אחידים, שהעמידו את הנחישות שלו במבחן. המורה שלו, מר קליין, הסביר שכדי לשלוט בכלי מיתרים צריך לבנות זיכרון שרירים לאט לאט." },
  { en:"Every afternoon, Daniel practiced holding the bow correctly and drawing it smoothly across open strings before even attempting a real song. At times, the repetition felt tedious, and he was tempted to quit.", he:"בכל אחר צהריים דניאל התאמן בהחזקת הקשת כראוי ובהעברתה בעדינות על מיתרים פתוחים, עוד לפני שניסה לנגן שיר אמיתי. לפעמים החזרות הרגישו משעממות, והוא התפתה לוותר." },
  { en:"However, after six months of steady daily practice, he played his first complete classical piece without a single mistake. That moment taught him that genuine skill grows through consistent effort rather than sudden shortcuts.", he:"אבל אחרי שישה חודשים של אימון יומי קבוע, הוא ניגן את היצירה הקלאסית השלמה הראשונה שלו בלי אף טעות. הרגע הזה לימד אותו שמיומנות אמיתית צומחת מתוך מאמץ עקבי, ולא מקיצורי דרך פתאומיים." } ]},
 { id:"n2_library", level:2, cover:"🏛️", title:"The Restored Library", he:"הספרייה המשוחזרת", blurb:"בניין נטוש ברחוב אלם מחכה למישהו שיאמין בו.", paras:[
  { en:"For nearly twenty years, the historic library on Elm Street stood empty with boarded windows and a leaking roof. Many residents assumed the old brick building would eventually be torn down.", he:"במשך כמעט עשרים שנה עמדה הספרייה ההיסטורית ברחוב אלם ריקה, עם חלונות מכוסים בקרשים וגג דולף. תושבים רבים הניחו שבניין הלבנים הישן ייהרס בסופו של דבר." },
  { en:"Fortunately, a group of local citizens organized a community project to save it. Architects, carpenters, and volunteers worked together for over a year to repair the roof, polish the original oak floors, and restore the tall arched windows. Local residents donated thousands of books to fill the newly built shelves.", he:"למרבה המזל, קבוצה של תושבים מקומיים ארגנה פרויקט קהילתי כדי להציל אותו. אדריכלים, נגרים ומתנדבים עבדו יחד יותר משנה כדי לתקן את הגג, להבריק את רצפות האלון המקוריות ולשחזר את החלונות הגבוהים והמקושתים. תושבי המקום תרמו אלפי ספרים כדי למלא את המדפים החדשים." },
  { en:"On the grand opening day, families walked through the bright, welcoming halls in amazement. The building was no longer a forgotten relic; it had become the vibrant educational heart of the neighborhood once again.", he:"ביום הפתיחה החגיגית, משפחות עברו בפליאה באולמות המוארים והמזמינים. הבניין כבר לא היה שריד נשכח; הוא הפך שוב ללב החינוכי התוסס של השכונה." } ]},
 { id:"n2_stars", level:2, cover:"⭐", title:"Navigating by the Stars", he:"ניווט לפי הכוכבים", blurb:"לילה במדבר הופך לשיעור בניווט עתיק.", paras:[
  { en:"Long before electronic compasses and digital maps existed, travelers across deserts and oceans relied entirely on the night sky to find their direction. During a summer camping trip in the desert, Uncle Avi decided to teach his nephews this ancient skill.", he:"הרבה לפני שהיו מצפנים אלקטרוניים ומפות דיגיטליות, מטיילים במדבריות ובאוקיינוסים הסתמכו לגמרי על שמי הלילה כדי למצוא את הכיוון. במהלך טיול קמפינג קיצי במדבר, הדוד אבי החליט ללמד את אחייניו את המיומנות העתיקה הזאת." },
  { en:"Away from city lights, the sky was remarkably clear. He first showed them how to locate the Big Dipper and trace an imaginary line from its two outer stars to find Polaris, the North Star.", he:"הרחק מאורות העיר, השמיים היו בהירים במיוחד. קודם כול הוא הראה להם איך למצוא את העגלה הגדולה ולמתוח קו דמיוני משני הכוכבים החיצוניים שלה כדי למצוא את פולאריס, כוכב הצפון." },
  { en:"Unlike other stars that appear to move across the sky as the Earth rotates, Polaris remains nearly fixed in the northern sky. By knowing which way was north, the boys quickly learned how to determine east, west, and south without looking at a single modern device.", he:"בניגוד לכוכבים אחרים, שנראים כאילו הם נעים בשמיים בזמן שכדור הארץ מסתובב, פולאריס נשאר כמעט קבוע בשמי הצפון. כשידעו איפה הצפון, הנערים למדו מהר איך לקבוע את המזרח, המערב והדרום בלי להסתכל על אף מכשיר מודרני." } ]},
 { id:"n2_ledger", level:2, cover:"🔍", title:"The Mystery of the Missing Ledger", he:"תעלומת ספר החשבונות", blurb:"ספר חשוב נעלם מהכספת, ומר גולד יוצא לחפש.", paras:[
  { en:"Mr. Gold ran a busy hardware store that had served the town for four decades. One Monday morning, he opened his office safe and discovered that his main accounting ledger from the previous year was missing.", he:"מר גולד ניהל חנות לכלי עבודה הומה, ששירתה את העיירה כבר ארבעה עשורים. ביום שני אחד בבוקר הוא פתח את הכספת במשרדו וגילה שספר החשבונות הראשי שלו מהשנה הקודמת נעלם." },
  { en:"He searched every drawer, checked the storage room, and asked his two assistants, but nobody had seen it. Calmly, Mr. Gold retraced his steps from Friday afternoon. He remembered carrying a stack of folders to the print shop down the street to make copies of supplier invoices.", he:"הוא חיפש בכל מגירה, בדק את המחסן ושאל את שני העוזרים שלו, אבל אף אחד לא ראה אותו. בשלווה, מר גולד שחזר את צעדיו מיום שישי אחר הצהריים. הוא נזכר שנשא ערימת תיקיות לבית הדפוס שבהמשך הרחוב, כדי לצלם עותקים של חשבוניות מספקים." },
  { en:"He immediately walked over to the shop and spoke with the manager. Sure enough, the brown leather ledger had been placed safely on a shelf behind the counter after it accidentally slipped out of his folders.", he:"מיד הוא הלך לבית הדפוס ודיבר עם המנהל. ואכן, ספר החשבונות מעור חום הונח בבטחה על מדף מאחורי הדלפק, אחרי שהחליק בטעות מתוך התיקיות שלו." } ]},
 { id:"n2_honeybees", level:2, cover:"🐝", title:"Cultivating Honeybees", he:"גידול דבורי דבש", blurb:"הצצה לעבודה השקטה של כוורן בקצה האחו.", paras:[
  { en:"At the edge of a quiet meadow, Benjamin keeps six wooden beehives painted white to reflect the summer sun. Beekeeping requires careful observation and respect for nature's rhythms.", he:"בקצה אחו שקט, בנימין מחזיק שש כוורות עץ שצבועות בלבן כדי להחזיר את אור שמש הקיץ. גידול דבורים דורש התבוננות זהירה וכבוד למקצבים של הטבע." },
  { en:"Wearing a protective veil and gloves, Benjamin inspects the hives every two weeks to check the health of the colony and ensure the queen bee is thriving. He watches how worker bees collect nectar from clover and wildflowers, bringing it back to store inside hexagonal wax cells.", he:"עם רשת מגן על הפנים וכפפות על הידיים, בנימין בודק את הכוורות כל שבועיים, כדי לבדוק את בריאות המושבה ולוודא שהמלכה משגשגת. הוא מתבונן איך הדבורים הפועלות אוספות צוף מתלתן ומפרחי בר, ומביאות אותו בחזרה כדי לאחסן אותו בתוך תאי שעווה משושים." },
  { en:"In late summer, when the frames are full and sealed with white wax, he harvests the golden honey without taking too much, always leaving plenty for the bees to survive the cold winter months ahead.", he:"בסוף הקיץ, כשהמסגרות מלאות וחתומות בשעווה לבנה, הוא אוסף את הדבש הזהוב בלי לקחת יותר מדי, ותמיד משאיר הרבה לדבורים כדי שישרדו את חודשי החורף הקרים שלפניהן." } ]},
 { id:"n2_weather_station", level:2, cover:"🏔️", title:"The Mountain Weather Station", he:"תחנת מזג האוויר בהרים", blurb:"מדען אחד, תחנה קטנה, ומזג אוויר שמשתנה בתוך דקות.", paras:[
  { en:"High above the tree line, where strong winds blow even in July, sits a small research station dedicated to studying mountain weather patterns. Dr. Lev works there for two weeks at a time, collecting data that helps forecasters predict storms for the valleys below.", he:"גבוה מעל קו העצים, במקום שבו נושבות רוחות חזקות אפילו ביולי, ניצבת תחנת מחקר קטנה שמוקדשת לחקר דפוסי מזג האוויר בהרים. ד\"ר לב עובד שם שבועיים בכל פעם, ואוסף נתונים שעוזרים לחזאים לחזות סופות בעמקים שלמטה." },
  { en:"Every three hours, he steps outside into the thin, crisp air to check instruments that measure barometric pressure, humidity, and snowfall. Because mountain weather can shift from bright sunshine to a blinding snowstorm within minutes, the station is built with thick stone walls and heavy shutters.", he:"כל שלוש שעות הוא יוצא החוצה לאוויר הדליל והצלול כדי לבדוק מכשירים שמודדים לחץ ברומטרי, לחות וכמות שלג. מכיוון שמזג האוויר בהרים יכול להשתנות משמש בהירה לסופת שלגים מסנוורת בתוך דקות, התחנה בנויה עם קירות אבן עבים ותריסים כבדים." },
  { en:"Despite the isolation, Dr. Lev enjoys the quiet focus the high altitude provides for his scientific writing.", he:"למרות הבידוד, ד\"ר לב נהנה מהריכוז השקט שהגובה הרב מעניק לכתיבה המדעית שלו." } ]},
 { id:"n2_calligraphy", level:2, cover:"🖋️", title:"The Art of Calligraphy", he:"אמנות הקליגרפיה", blurb:"עט, דיו ונייר - והדרך האיטית ליצור אותיות יפות.", paras:[
  { en:"In an age dominated by keyboards and touchscreens, Sarah finds peace in the slow, deliberate art of calligraphy. Using a wooden dip pen, a bottle of black India ink, and smooth cotton paper, she practices forming elegant letters with balanced proportions.", he:"בעידן שבו שולטים מקלדות ומסכי מגע, שרה מוצאת שלווה באמנות האיטית והמכוונת של הקליגרפיה. בעזרת עט טבילה מעץ, בקבוק של דיו הודי שחור ונייר כותנה חלק, היא מתאמנת ביצירת אותיות אלגנטיות בפרופורציות מאוזנות." },
  { en:"Unlike regular handwriting, calligraphy requires controlling the pressure on the metal nib—pressing slightly harder on downward strokes to create thick lines and lifting gently on upward strokes for thin, delicate curves. If she rushes, the ink blots or the lines look uneven.", he:"בניגוד לכתב יד רגיל, קליגרפיה דורשת שליטה בלחץ על החוד המתכתי - ללחוץ מעט חזק יותר בתנועות כלפי מטה כדי ליצור קווים עבים, ולהרים בעדינות בתנועות כלפי מעלה כדי ליצור קימורים דקים ועדינים. אם היא ממהרת, הדיו נמרח או שהקווים נראים לא אחידים." },
  { en:"Practicing for thirty minutes each evening helps her slow down after a busy workday, turning simple words into thoughtful works of visual craftsmanship.", he:"אימון של שלושים דקות בכל ערב עוזר לה להאט אחרי יום עבודה עמוס, והופך מילים פשוטות ליצירות מחושבות של אומנות חזותית." } ]},
 { id:"n2_local_history", level:2, cover:"📦", title:"Discovering Local History", he:"מגלים היסטוריה מקומית", blurb:"שיפוץ במרתף חושף סוד ישן מאחורי הקיר.", paras:[
  { en:"While renovating the basement of his old house, David found a sealed tin box hidden behind a loose brick in the wall. Curious, he opened it carefully and found several yellowed newspapers from 1924, an old brass key, and a handwritten journal belonging to the house's original builder.", he:"בזמן ששיפץ את המרתף של ביתו הישן, דוד מצא קופסת פח סגורה היטב שהוסתרה מאחורי לבנה רופפת בקיר. מתוך סקרנות הוא פתח אותה בזהירות, ומצא בה כמה עיתונים מצהיבים משנת 1924, מפתח פליז ישן ויומן בכתב יד של מי שבנה את הבית במקור." },
  { en:"Reading through the faded ink entries, David learned how the neighborhood had once been surrounded by apple farms and how residents worked together to build the town's first schoolhouse.", he:"כשקרא את הרשומות שנכתבו בדיו דהויה, דוד למד שפעם השכונה הייתה מוקפת במטעי תפוחים, ושהתושבים עבדו יחד כדי לבנות את בית הספר הראשון של העיירה." },
  { en:"Excited by his discovery, he donated the newspapers to the local historical museum so other residents could read about the early days of their community.", he:"נרגש מהתגלית שלו, הוא תרם את העיתונים למוזיאון ההיסטורי המקומי, כדי שגם תושבים אחרים יוכלו לקרוא על הימים הראשונים של הקהילה שלהם." } ]},
 { id:"n2_bridge", level:2, cover:"🌉", title:"The Bridge Over the River", he:"הגשר מעל הנהר", blurb:"לחקלאים בצד המערבי של הנהר יש דרך ארוכה מדי לשוק.", paras:[
  { en:"For decades, farmers living on the west side of the river had to drive twenty miles north to reach the nearest market town because no bridge existed nearby. Last year, civil engineers finally began constructing a sturdy stone and steel bridge across the narrowest point of the canyon.", he:"במשך עשרות שנים, חקלאים שגרו בצד המערבי של הנהר נאלצו לנסוע עשרים מייל צפונה כדי להגיע לעיירת השוק הקרובה, כי לא היה שום גשר בסביבה. בשנה שעברה, מהנדסים אזרחיים התחילו סוף סוף לבנות גשר חזק מאבן ופלדה מעל הנקודה הצרה ביותר של הקניון." },
  { en:"Residents watched with fascination as workers poured deep concrete foundations into the riverbanks and used massive cranes to lift steel beams into place.", he:"התושבים צפו בסקרנות רבה כשהפועלים יצקו יסודות בטון עמוקים לתוך גדות הנהר, והשתמשו במנופים ענקיים כדי להרים קורות פלדה למקומן." },
  { en:"When the bridge officially opened this spring, the twenty-mile journey was reduced to a five-minute drive. Trade between the farms and the town flourished immediately, benefiting everyone in the region.", he:"כשהגשר נפתח רשמית באביב הזה, הנסיעה של עשרים מייל התקצרה לנסיעה של חמש דקות. המסחר בין החוות לעיירה שגשג מיד, לטובת כל תושבי האזור." } ]},
 { id:"n2_ceramics", level:2, cover:"🏺", title:"The Ceramic Workshop", he:"סדנת הקרמיקה", blurb:"מגוש חימר אפור ועד כלי מבריק - צעד אחר צעד.", paras:[
  { en:"Inside a sunlit studio on the edge of town, pottery wheels spin quietly as students shape lumps of gray clay into bowls, mugs, and pitchers. Learning to center clay on a spinning wheel is harder than it looks; even slight uneven pressure causes the clay to wobble.", he:"בסטודיו מואר בשמש בקצה העיירה, אובניים מסתובבים בשקט בזמן שתלמידים מעצבים גושי חימר אפור לקערות, לספלים ולכדים. ללמוד להעמיד את החימר בדיוק במרכז גלגל הקדרות המסתובב קשה יותר ממה שזה נראה; אפילו לחץ קצת לא אחיד גורם לחימר להתנדנד." },
  { en:"Instructor Rachel guides her students to keep their elbows steady and use calm, consistent hand movements.", he:"המדריכה רחל מנחה את התלמידים שלה לשמור על מרפקים יציבים ולהשתמש בתנועות ידיים רגועות ועקביות." },
  { en:"Once a piece is shaped, it dries slowly for several days before being baked in a hot kiln at over a thousand degrees. After cooling, students apply colorful mineral glazes and fire the pottery a second time, revealing glossy, durable kitchenware.", he:"אחרי שכלי מקבל את צורתו, הוא מתייבש לאט במשך כמה ימים, ואז נשרף בכבשן חם ביותר מאלף מעלות. אחרי שהוא מתקרר, התלמידים מורחים עליו זיגוגים מינרליים צבעוניים ושורפים אותו פעם שנייה, וכך מתגלים כלי מטבח מבריקים ועמידים." } ]},
 { id:"n2_power_outage", level:2, cover:"🕯️", title:"A Winter Power Outage", he:"הפסקת חשמל בחורף", blurb:"סערת שלג משאירה שכונה שלמה בחושך.", paras:[
  { en:"During a severe January storm, heavy wet snow snapped several power lines, leaving the entire neighborhood without electricity for two days. Instead of panicking, the Miller family quickly organized their home for the cold.", he:"במהלך סערה קשה בינואר, שלג כבד ורטוב קרע כמה קווי חשמל, והשאיר את כל השכונה בלי חשמל במשך יומיים. במקום להיבהל, משפחת מילר הכינה מהר את הבית לקראת הקור." },
  { en:"They gathered blankets into the living room to conserve warmth, lit emergency candles safely inside glass jars, and used a battery-powered radio to listen to local weather updates.", he:"הם אספו שמיכות לסלון כדי לשמור על החום, הדליקו נרות חירום בבטחה בתוך צנצנות זכוכית, והשתמשו ברדיו על סוללות כדי להאזין לעדכוני מזג אוויר מקומיים." },
  { en:"Without television or internet, the evening became surprisingly memorable. They played board games by candlelight, told stories from their childhood, and cooked warm meals on a small camping stove until utility crews finally restored power on Sunday morning.", he:"בלי טלוויזיה ואינטרנט, הערב הפך לבלתי נשכח באופן מפתיע. הם שיחקו משחקי קופסה לאור נרות, סיפרו סיפורים מהילדות שלהם ובישלו ארוחות חמות על כירת קמפינג קטנה, עד שצוותי החשמל החזירו סוף סוף את החשמל ביום ראשון בבוקר." } ]},
 { id:"n2_conservatory", level:2, cover:"🌿", title:"The Botanical Conservatory", he:"החממה הבוטנית", blurb:"בלב העיר מסתתר עולם ירוק וחמים.", paras:[
  { en:"In the center of the bustling city stands a massive glass greenhouse known as the Botanical Conservatory. Stepping through its heavy brass doors feels like entering another climate entirely.", he:"במרכז העיר ההומה ניצבת חממת זכוכית ענקית שנקראת החממה הבוטנית. המעבר בדלתות הפליז הכבדות שלה מרגיש כמו כניסה לאקלים אחר לגמרי." },
  { en:"Warm, humid air surrounds visitors as they walk along stone paths lined with giant ferns, towering palm trees, and rare orchids from around the world. Botanists carefully regulate the temperature and misting systems in different sections of the glass building to recreate desert, rainforest, and mountain environments.", he:"אוויר חם ולח עוטף את המבקרים כשהם הולכים בשבילי אבן, שלאורכם שרכים ענקיים, עצי דקל מתנשאים וסחלבים נדירים מכל העולם. בוטנאים מווסתים בקפידה את הטמפרטורה ואת מערכות הערפול באגפים השונים של בניין הזכוכית, כדי ליצור מחדש סביבות של מדבר, יער גשם והרים." },
  { en:"For city residents seeking a quiet escape during cold winter months, a walk through the sunlit conservatory offers an immediate connection to the natural world.", he:"לתושבי העיר שמחפשים מפלט שקט בחודשי החורף הקרים, טיול בחממה המוארת בשמש מציע חיבור מיידי לעולם הטבע." } ]},
 { id:"n2_antique_books", level:2, cover:"📖", title:"Repairing Antique Books", he:"משקמים ספרים עתיקים", blurb:"הצצה לעבודה העדינה של מי ששומר על ספרים ישנים.", paras:[
  { en:"Old books often carry histories just as interesting as the words printed on their pages. At the university archive, specialist Samuel repairs damaged leather bindings and torn paper from centuries ago.", he:"לספרים ישנים יש לעיתים קרובות היסטוריה מעניינת בדיוק כמו המילים שמודפסות בדפים שלהם. בארכיון האוניברסיטה, המומחה שמואל מתקן כריכות עור פגומות ונייר קרוע מלפני מאות שנים." },
  { en:"Working with fine brushes, archival paste, and thin Japanese tissue paper, he carefully reinforces fragile pages without covering the original ink. When a book's spine has crumbled, he sews the signatures back together by hand using strong linen thread before attaching new boards covered in matching cloth.", he:"בעזרת מכחולים עדינים, דבק מיוחד לשימור ונייר טישו יפני דק, הוא מחזק בזהירות דפים שבירים בלי לכסות את הדיו המקורי. כשגב של ספר התפורר, הוא תופר ביד את קבוצות הדפים בחזרה בחוט פשתן חזק, ואז מחבר כריכות חדשות מצופות בבד תואם." },
  { en:"His quiet, meticulous work ensures that valuable historical texts remain readable for scholars and students for generations to come.", he:"העבודה השקטה והקפדנית שלו מבטיחה שטקסטים היסטוריים יקרי ערך יישארו קריאים לחוקרים ולסטודנטים עוד דורות רבים." } ]},
 { id:"n2_solar_cabin", level:2, cover:"☀️", title:"The Solar-Powered Cabin", he:"הבקתה הסולארית", blurb:"אדריכל מתכנן בקתה שלא צריכה את רשת החשמל.", paras:[
  { en:"When architect Noah designed his weekend cabin in the hills, he wanted it to operate completely independent of the city power grid. He installed twenty high-efficiency solar panels across the south-facing roof to capture maximum sunlight throughout the day.", he:"כשהאדריכל נח תכנן את בקתת סוף השבוע שלו בגבעות, הוא רצה שהיא תפעל באופן עצמאי לגמרי, בלי רשת החשמל של העיר. הוא התקין עשרים פאנלים סולאריים יעילים במיוחד על הגג הפונה דרומה, כדי לקלוט כמה שיותר אור שמש לאורך היום." },
  { en:"Excess energy is stored in a bank of heavy-duty batteries in the basement, providing reliable electricity throughout the night and during cloudy days. Large windows were positioned strategically to let in warm winter sunlight while deep roof overhangs block the harsh summer heat.", he:"עודפי האנרגיה נאגרים במערך של סוללות חזקות במרתף, ומספקים חשמל אמין לאורך הלילה ובימים מעוננים. חלונות גדולים מוקמו בתכנון מחושב כדי להכניס את אור השמש החמים של החורף, ואילו שולי גג עמוקים חוסמים את חום הקיץ הקשה." },
  { en:"The cabin proves that thoughtful engineering can provide modern comfort while working in harmony with the surrounding landscape.", he:"הבקתה מוכיחה שהנדסה מחושבת יכולה לספק נוחות מודרנית ובו בזמן לעבוד בהרמוניה עם הנוף שמסביב." } ]},
 { id:"n3_cartographers_dilemma", level:3, cover:"🗺️", title:"The Cartographer's Dilemma", he:"הדילמה של הקרטוגרף", blurb:"למה כל מפה של העולם משקרת קצת, ומה זה אומר עלינו.", paras:[
  { en:"Every flat map of the Earth is, by mathematical necessity, an imperfect compromise. Because it is impossible to flatten the curved surface of a three-dimensional sphere onto a two-dimensional sheet of paper without stretching, tearing, or compressing some part of the image, cartographers must constantly decide which geographic truth to preserve and which to sacrifice.", he:"כל מפה שטוחה של כדור הארץ היא, מתוך הכרח מתמטי, פשרה לא מושלמת. מכיוון שאי אפשר לשטח את פני השטח המעוקלים של כדור תלת-ממדי על גבי דף נייר דו-ממדי בלי למתוח, לקרוע או לדחוס חלק כלשהו מהתמונה, הקרטוגרפים נאלצים להחליט כל הזמן איזו אמת גאוגרפית לשמר ואיזו להקריב." },
  { en:"In 1569, Gerardus Mercator introduced a cylindrical projection that revolutionized maritime navigation because every straight line drawn on his map represented a constant compass bearing.", he:"בשנת 1569 הציג גרארדוס מרקטור היטל גלילי שחולל מהפכה בניווט הימי, משום שכל קו ישר ששורטט על המפה שלו ייצג כיוון מצפן קבוע." },
  { en:"However, this navigational convenience came at a significant visual cost: landmasses near the poles appeared dramatically larger than their true proportions, making Greenland look nearly as vast as Africa, even though Africa is fourteen times larger.", he:"אולם הנוחות הניווטית הזו באה במחיר חזותי משמעותי: יבשות הסמוכות לקטבים נראו גדולות בהרבה מממדיהן האמיתיים, כך שגרינלנד נראתה גדולה כמעט כמו אפריקה, אף שאפריקה גדולה ממנה פי ארבעה-עשר." },
  { en:"Today, digital mapping systems switch dynamically between projections depending on zoom level, reminding us that how we choose to represent the world inevitably shapes how we perceive it.", he:"כיום, מערכות מיפוי דיגיטליות עוברות באופן דינמי בין היטלים שונים בהתאם לרמת התקריב, ומזכירות לנו שהאופן שבו אנו בוחרים לייצג את העולם מעצב בהכרח את האופן שבו אנו תופסים אותו." } ]},
 { id:"n3_monarch_migration", level:3, cover:"🦋", title:"The Migration of the Monarch", he:"נדידת פרפר המונרך", blurb:"מסע של אלפי קילומטרים שאף פרפר אחד לא משלים לבדו.", paras:[
  { en:"Every autumn, millions of monarch butterflies embark on one of the most extraordinary navigational feats in the natural world, traveling up to three thousand miles from southern Canada and the northern United States to specific mountain forests in central Mexico. What makes this journey truly astonishing is that no single butterfly completes the entire round-trip cycle.", he:"בכל סתיו יוצאים מיליוני פרפרי מונרך לאחד ממבצעי הניווט המופלאים ביותר בטבע, ונודדים עד שלושת אלפים מייל מדרום קנדה ומצפון ארצות הברית אל יערות הרריים מסוימים במרכז מקסיקו. מה שהופך את המסע הזה למדהים באמת הוא שאף פרפר בודד אינו משלים את מחזור ההלוך-ושוב כולו." },
  { en:"The monarchs flying south in autumn belong to a specialized 'super-generation' that lives up to eight months—nearly ten times longer than their summer ancestors.", he:"המונרכים שעפים דרומה בסתיו שייכים ל'דור-על' מיוחד שחי עד שמונה חודשים – כמעט פי עשרה מאבותיהם של הקיץ." },
  { en:"Guided by an internal circadian clock combined with a sun compass in their antennae and sensitivity to the Earth's magnetic field, they arrive at the exact same groves of oyamel fir trees that their great-great-grandparents occupied the previous winter. Scientists continue to study how such complex spatial memory is encoded within a brain no larger than the head of a pin.", he:"בהכוונת שעון ביולוגי פנימי, יחד עם מצפן שמש באנטנות שלהם ורגישות לשדה המגנטי של כדור הארץ, הם מגיעים בדיוק לאותן חורשות של עצי אשוח אויאמל שבהן שהו סבי-סביהם בחורף הקודם. מדענים ממשיכים לחקור כיצד זיכרון מרחבי מורכב כל כך מקודד במוח שאינו גדול מראש של סיכה." } ]},
 { id:"n3_seed_vault", level:3, cover:"🌱", title:"The Preservation of Seed Vaults", he:"כספת הזרעים", blurb:"כספת קפואה בקצה העולם ששומרת על עתיד המזון של כולנו.", paras:[
  { en:"Deep inside a sandstone mountain on the remote Arctic island of Svalbard, well above the Arctic Circle, lies a reinforced concrete tunnel designed to safeguard the future of global agriculture.", he:"עמוק בתוך הר אבן חול באי הארקטי המרוחק סבאלברד, הרחק מצפון לחוג הקוטב הצפוני, שוכנת מנהרת בטון מזוין שנועדה להגן על עתידה של החקלאות העולמית." },
  { en:"The Svalbard Global Seed Vault houses over a million duplicate seed samples from nearly every country on Earth, preserved at a constant temperature of minus eighteen degrees Celsius. Even if electrical power were to fail completely, the surrounding permafrost would keep the seeds frozen for decades.", he:"כספת הזרעים העולמית בסבאלברד מכילה יותר ממיליון דגימות זרעים כפולות מכמעט כל מדינה בעולם, השמורות בטמפרטורה קבועה של מינוס שמונה-עשרה מעלות צלזיוס. גם אם אספקת החשמל תיפסק לגמרי, הפרמפרוסט (הקרקע הקפואה תמיד) שמסביב ישמור על הזרעים קפואים במשך עשרות שנים." },
  { en:"Agricultural historians warn that over the past century, global farming has grown increasingly reliant on a narrow selection of high-yield crop varieties, leaving food supplies vulnerable to new plant diseases or shifting climate conditions. By storing ancient and regional varieties of wheat, rice, barley, and legumes in a secure, neutral location, scientists ensure that plant breeders will always have access to the genetic diversity necessary to cultivate resilient crops.", he:"היסטוריונים של החקלאות מזהירים שבמאה האחרונה החקלאות העולמית נעשתה תלויה יותר ויותר במבחר מצומצם של זני גידולים עתירי יבול, דבר שמשאיר את אספקת המזון פגיעה למחלות צמחים חדשות או לשינויים בתנאי האקלים. באמצעות אחסון זנים עתיקים ומקומיים של חיטה, אורז, שעורה וקטניות במקום מאובטח וניטרלי, המדענים מבטיחים שלמגדלי הצמחים תמיד תהיה גישה למגוון הגנטי הדרוש לגידול יבולים עמידים." } ]},
 { id:"n3_timekeeping", level:3, cover:"🕰️", title:"The Evolution of Timekeeping", he:"התפתחות מדידת הזמן", blurb:"איך הרכבות הכריחו את העולם כולו לכוון את השעון.", paras:[
  { en:"For thousands of years, human societies measured time according to the natural rhythms of the sun, moon, and seasons, using sundials, water clocks, and hourglasses that varied slightly from town to town. As long as travel moved at the speed of a horse or a sailing ship, minor differences in local time caused no practical inconvenience.", he:"במשך אלפי שנים מדדו חברות אנושיות את הזמן לפי המקצבים הטבעיים של השמש, הירח ועונות השנה, בעזרת שעוני שמש, שעוני מים ושעוני חול שהיו שונים מעט מעיר לעיר. כל עוד הנסיעות התנהלו במהירות של סוס או של ספינת מפרש, הבדלים קטנים בזמן המקומי לא גרמו לשום אי-נוחות מעשית." },
  { en:"That changed dramatically in the nineteenth century with the rapid expansion of transcontinental railways. When dozens of towns operated on their own local solar time, scheduling trains safely on single-track lines became an administrative nightmare, leading to frequent delays and dangerous collisions.", he:"המצב השתנה באופן דרמטי במאה התשע-עשרה, עם ההתפשטות המהירה של מסילות הרכבת החוצות יבשות. כאשר עשרות עיירות פעלו כל אחת לפי זמן השמש המקומי שלה, תזמון בטוח של רכבות על מסילות יחידות הפך לסיוט מנהלי, שהוביל לעיכובים תכופים ולהתנגשויות מסוכנות." },
  { en:"In response, railway companies and governments established standardized time zones, dividing the globe into twenty-four longitudinal sections. What began as a logistical necessity for train schedules ultimately synchronized global commerce, communications, and daily life around an invisible, unified clock.", he:"בתגובה, חברות הרכבת והממשלות קבעו אזורי זמן אחידים, וחילקו את כדור הארץ לעשרים וארבעה חלקים לפי קווי אורך. מה שהתחיל כצורך לוגיסטי עבור לוחות הזמנים של הרכבות, סנכרן בסופו של דבר את המסחר העולמי, את התקשורת ואת חיי היומיום סביב שעון אחיד ובלתי נראה." } ]},
 { id:"n3_acoustic_design", level:3, cover:"🎼", title:"The Science of Acoustic Design", he:"המדע של תכנון אקוסטי", blurb:"איך הופכים אולם קונצרטים שלם לכלי נגינה אחד.", paras:[
  { en:"Designing a world-class concert hall is as much an exercise in applied physics as it is in visual architecture. When an orchestra plays a single note, sound waves radiate outward in every direction, striking walls, ceilings, and balconies before reaching the listener's ears.", he:"תכנון אולם קונצרטים ברמה עולמית הוא תרגיל בפיזיקה שימושית לא פחות משהוא תרגיל באדריכלות חזותית. כאשר תזמורת מנגנת צליל יחיד, גלי קול מתפשטים החוצה לכל הכיוונים, ופוגעים בקירות, בתקרות וביציעים לפני שהם מגיעים לאוזני המאזין." },
  { en:"If a hall absorbs too much sound, the music sounds dry and lifeless; if sound reflects excessively without control, overlapping echoes blur fast musical passages into an indistinct roar.", he:"אם האולם בולע יותר מדי קול, המוזיקה נשמעת יבשה וחסרת חיים; ואם הקול מוחזר יותר מדי בלי שליטה, הדים חופפים מטשטשים קטעים מוזיקליים מהירים לכדי שאון בלתי ברור." },
  { en:"Acoustic engineers address this by carefully calculating reverberation time—the exact fraction of a second it takes for sound to fade after the source stops. They use convex wooden panels to scatter sound evenly across the auditorium, variable fabric banners to adjust absorption for different musical ensembles, and isolated structural foundations to block vibrations from nearby street traffic.", he:"מהנדסי אקוסטיקה מתמודדים עם זה באמצעות חישוב קפדני של זמן ההדהוד – החלק המדויק של השנייה שנדרש לקול לדעוך לאחר שמקורו נפסק. הם משתמשים בלוחות עץ קמורים כדי לפזר את הקול באופן שווה ברחבי האולם, ביריעות בד מתכווננות כדי להתאים את בליעת הקול להרכבים מוזיקליים שונים, וביסודות מבניים מבודדים כדי לחסום רעידות מתנועת כלי הרכב ברחובות הסמוכים." },
  { en:"When engineered properly, the hall itself becomes a finely tuned instrument.", he:"כאשר הוא מתוכנן כראוי, האולם עצמו הופך לכלי נגינה מכוון היטב." } ]},
 { id:"n3_language_of_trees", level:3, cover:"🌳", title:"The Silent Language of Trees", he:"השפה השקטה של העצים", blurb:"מתחת לאדמה, העצים ביער מדברים זה עם זה ועוזרים זה לזה.", paras:[
  { en:"Beneath the quiet floor of an undisturbed forest lies an intricate biological network that challenges the traditional view of trees as solitary competitors. Through microscopic fungal threads known as mycorrhizae that attach to tree roots, neighboring trees exchange water, carbon, and essential nutrients across vast underground pathways.", he:"מתחת לקרקעית השקטה של יער שלא הופרע שוכנת רשת ביולוגית מורכבת, שמערערת על התפיסה המסורתית של עצים כמתחרים בודדים. באמצעות חוטי פטריות מיקרוסקופיים המכונים מיקוריזה, הנצמדים לשורשי העצים, עצים שכנים מחליפים ביניהם מים, פחמן וחומרי הזנה חיוניים לאורך מסלולים תת-קרקעיים נרחבים." },
  { en:"Forest ecologists have discovered that older, taller 'mother trees' with deep roots and full access to sunlight frequently transfer surplus sugars through these fungal networks to younger saplings growing in the deep shade below, significantly increasing their chances of survival.", he:"אקולוגים של יערות גילו ש'עצי אם' ותיקים וגבוהים יותר, בעלי שורשים עמוקים וגישה מלאה לאור השמש, מעבירים לעיתים קרובות עודפי סוכרים דרך רשתות הפטריות האלה אל שתילים צעירים הגדלים בצל העמוק שמתחתם, ומגדילים באופן משמעותי את סיכויי ההישרדות שלהם." },
  { en:"Furthermore, when a tree is attacked by insects, it can transmit chemical warning signals through the underground web, prompting nearby trees to increase their production of defensive compounds before the pests even arrive. Far from being a collection of isolated trunks, a healthy forest functions as a cooperative, interconnected community.", he:"יתרה מזאת, כאשר עץ מותקף על ידי חרקים, הוא יכול לשדר אותות אזהרה כימיים דרך הרשת התת-קרקעית, וכך לגרום לעצים סמוכים להגביר את ייצור החומרים המגינים שלהם עוד לפני שהמזיקים מגיעים. רחוק מלהיות אוסף של גזעים מבודדים, יער בריא מתפקד כקהילה שיתופית ומקושרת." } ]},
 { id:"n3_ocean_trenches", level:3, cover:"🌊", title:"The Deep Ocean Trenches", he:"התעלות העמוקות באוקיינוס", blurb:"במקום החשוך והעמוק ביותר בעולם, החיים מוצאים דרך.", paras:[
  { en:"While humanity has mapped the surfaces of Mars and the Moon in remarkable detail, vast stretches of Earth's own ocean floor remain largely unexplored. Nearly seven miles beneath the surface of the western Pacific Ocean lies the Mariana Trench, a crescent-shaped canyon where tectonic plates collide and plunge downward into the Earth's mantle.", he:"אף שהאנושות מיפתה את פני השטח של מאדים ושל הירח בפירוט מרשים, חלקים עצומים מקרקעית האוקיינוס של כדור הארץ עצמו נותרו ברובם בלתי נחקרים. כמעט שבעה מיילים מתחת לפני האוקיינוס השקט המערבי שוכן תעלת מריאנה, קניון בצורת סהר שבו לוחות טקטוניים מתנגשים וצוללים מטה אל תוך מעטפת כדור הארץ." },
  { en:"At this extreme depth, the environment is defined by perpetual darkness, near-freezing temperatures, and crushing hydrostatic pressure exceeding eight tons per square inch—enough to flatten conventional submarines instantly.", he:"בעומק קיצוני זה, הסביבה מוגדרת על ידי חושך נצחי, טמפרטורות הקרובות לקפיאה ולחץ הידרוסטטי מוחץ העולה על שמונה טונות לאינץ' רבוע – מספיק כדי למעוך צוללות רגילות ברגע." },
  { en:"Yet specialized unmanned submersibles reinforced with thick titanium spheres and syntactic foam have descended to the trench floor and discovered thriving ecosystems. Organisms there survive without sunlight by relying on chemosynthesis, converting minerals escaping from deep hydrothermal vents into energy, expanding scientific understanding of the limits where life can exist.", he:"ובכל זאת, צוללות מחקר מיוחדות ובלתי מאוישות, המחוזקות בכדורי טיטניום עבים ובקצף סינטקטי, ירדו עד קרקעית התעלה וגילו מערכות אקולוגיות משגשגות. האורגניזמים שם שורדים בלי אור שמש בזכות כימוסינתזה – הם הופכים מינרלים הנפלטים מארובות הידרותרמיות עמוקות לאנרגיה – וכך מרחיבים את ההבנה המדעית לגבי הגבולות שבהם חיים יכולים להתקיים." } ]},
 { id:"n3_printing_press", level:3, cover:"📜", title:"The Printing Press and Knowledge", he:"הדפוס והידע", blurb:"המכונה ששינתה את הדרך שבה האנושות לומדת וחושבת.", paras:[
  { en:"Before the mid-fifteenth century, producing a single book in Europe required months of painstaking labor by skilled scribes copying text onto parchment by hand. Because books were extraordinarily expensive and rare, literacy remained confined largely to scholars and wealthy elites, and scientific discoveries spread slowly across disconnected regions.", he:"לפני אמצע המאה החמש-עשרה, הפקת ספר יחיד באירופה דרשה חודשים של עבודה מפרכת מצד סופרים מיומנים שהעתיקו טקסט על קלף בכתב יד. מכיוון שספרים היו יקרים ונדירים במיוחד, ידיעת קרוא וכתוב נשארה מוגבלת בעיקר למלומדים ולאליטות עשירות, ותגליות מדעיות התפשטו לאט בין אזורים מנותקים." },
  { en:"When Johannes Gutenberg combined movable metal type, oil-based ink, and a mechanical screw press in Mainz, he fundamentally altered the trajectory of human knowledge. Within fifty years, printing workshops operated in over two hundred cities, producing millions of volumes at a fraction of their previous cost.", he:"כאשר יוהאנס גוטנברג שילב אותיות מתכת נפרדות להרכבה, דיו על בסיס שמן ומכבש בורג מכני במיינץ, הוא שינה מן היסוד את מסלולו של הידע האנושי. בתוך חמישים שנה פעלו בתי דפוס ביותר ממאתיים ערים, והפיקו מיליוני כרכים בשבריר מעלותם הקודמת." },
  { en:"Standardized texts allowed scholars across distant universities to examine identical diagrams, verify mathematical tables, and build upon one another's work systematically, laying the intellectual groundwork for the scientific and industrial revolutions that followed.", he:"טקסטים אחידים אפשרו למלומדים באוניברסיטאות מרוחקות לבחון תרשימים זהים, לאמת טבלאות מתמטיות ולבנות באופן שיטתי זה על עבודתו של זה, וכך הניחו את התשתית האינטלקטואלית למהפכה המדעית ולמהפכה התעשייתית שבאו אחר כך." } ]},
 { id:"n3_supply_chain", level:3, cover:"🚢", title:"The Principles of Supply Chain Logistics", he:"עקרונות הלוגיסטיקה של שרשרת האספקה", blurb:"המסע הארוך והמסובך שעושה כל פרי עד שהוא מגיע למדף.", paras:[
  { en:"Behind the seemingly effortless experience of walking into a neighborhood supermarket and finding fresh produce from around the world lies one of modern civilization's most complex logistical systems. Global supply chains rely on synchronized coordination among farmers, freight carriers, customs officials, cold-storage warehouses, and local distributors.", he:"מאחורי החוויה שנראית כל כך פשוטה – להיכנס לסופרמרקט השכונתי ולמצוא תוצרת טרייה מכל העולם – מסתתרת אחת המערכות הלוגיסטיות המורכבות ביותר של הציוויליזציה המודרנית. שרשראות אספקה גלובליות נשענות על תיאום מסונכרן בין חקלאים, מובילי מטענים, פקידי מכס, מחסני קירור ומפיצים מקומיים." },
  { en:"To keep perishable goods fresh, refrigerated shipping containers maintain precise temperature and humidity levels throughout ocean voyages lasting several weeks. Modern logistics managers use predictive data models to anticipate seasonal demand shifts, reroute shipments around severe weather or congested ports, and minimize inventory waste.", he:"כדי לשמור על טריותן של סחורות מתכלות, מכולות שילוח מקוררות שומרות על רמות מדויקות של טמפרטורה ולחות לאורך הפלגות באוקיינוס הנמשכות כמה שבועות. מנהלי לוגיסטיקה מודרניים משתמשים במודלים חזויים מבוססי נתונים כדי לצפות שינויים עונתיים בביקוש, להסיט משלוחים מסביב למזג אוויר קשה או לנמלים עמוסים, ולצמצם בזבוז מלאי." },
  { en:"However, recent global disruptions have highlighted the fragility of overly lean 'just-in-time' systems, prompting many companies to diversify suppliers and maintain regional buffer stocks to ensure stability during unexpected crises.", he:"אולם שיבושים עולמיים בשנים האחרונות חשפו את השבריריות של מערכות 'בדיוק בזמן' רזות מדי, והניעו חברות רבות לגוון את הספקים שלהן ולהחזיק מלאי ביטחון אזורי כדי להבטיח יציבות בזמן משברים בלתי צפויים." } ]},
 { id:"n3_desalination", level:3, cover:"💧", title:"Desalination and Water Security", he:"התפלה וביטחון מים", blurb:"איך הופכים מי ים מלוחים למים שאפשר לשתות.", paras:[
  { en:"Although water covers roughly seventy percent of the Earth's surface, less than three percent of it is freshwater, and most of that is locked away in glaciers or deep underground aquifers. For arid coastal nations facing growing populations and limited rainfall, converting abundant seawater into clean drinking water has become an essential pillar of national infrastructure.", he:"אף שמים מכסים כשבעים אחוז מפני השטח של כדור הארץ, פחות משלושה אחוזים מהם הם מים מתוקים, ורובם כלואים בקרחונים או באקוויפרים (מאגרי מי תהום) עמוקים מתחת לאדמה. עבור מדינות חוף צחיחות המתמודדות עם אוכלוסייה גדלה ומשקעים מועטים, הפיכת מי הים הזמינים בשפע למי שתייה נקיים הפכה לעמוד תווך חיוני של התשתית הלאומית." },
  { en:"Modern desalination plants rely primarily on reverse osmosis, a process in which seawater is forced at high pressure through semi-permeable membranes with microscopic pores that allow water molecules to pass while blocking dissolved salts and impurities.", he:"מתקני התפלה מודרניים מבוססים בעיקר על אוסמוזה הפוכה, תהליך שבו מי ים נדחסים בלחץ גבוה דרך ממברנות חדירות למחצה בעלות נקבוביות מיקרוסקופיות, שמאפשרות למולקולות המים לעבור וחוסמות מלחים מומסים וזיהומים." },
  { en:"While early desalination facilities required prohibitive amounts of electricity, advances in energy-recovery turbines and solar integration have dramatically reduced operating costs, turning once-barren coastal regions into thriving agricultural and urban centers.", he:"בעוד שמתקני ההתפלה הראשונים דרשו כמויות חשמל עצומות עד כדי כך שהיו כמעט בלתי משתלמים, התקדמות בטורבינות להשבת אנרגיה ובשילוב אנרגיה סולארית הפחיתה באופן דרמטי את עלויות התפעול, והפכה אזורי חוף שהיו פעם שוממים למרכזים חקלאיים ועירוניים משגשגים." } ]},
 { id:"n3_urban_green_spaces", level:3, cover:"🏞️", title:"Urban Green Spaces and Well-Being", he:"שטחים ירוקים בעיר ואיכות חיים", blurb:"למה עצים ופארקים הם לא רק קישוט אלא צורך אמיתי בעיר.", paras:[
  { en:"As cities grow denser and concrete structures replace natural landscapes, urban planners increasingly recognize that public parks and tree-lined avenues are not merely decorative luxuries, but vital infrastructure for public health.", he:"ככל שהערים נעשות צפופות יותר ומבני בטון מחליפים את הנופים הטבעיים, מתכנני ערים מכירים יותר ויותר בכך שפארקים ציבוריים ושדרות מוצלות בעצים אינם רק מותרות לנוי, אלא תשתית חיונית לבריאות הציבור." },
  { en:"Studies conducted across major metropolitan areas consistently show that neighborhoods with accessible green spaces experience lower summer temperatures due to tree canopy shade and natural cooling, mitigating the 'urban heat island' effect. Furthermore, trees and soil absorb heavy rainwater, reducing strain on municipal drainage systems during severe storms.", he:"מחקרים שנערכו בערים גדולות רבות מראים בעקביות ששכונות עם שטחים ירוקים נגישים חוות טמפרטורות נמוכות יותר בקיץ בזכות הצל של צמרות העצים והקירור הטבעי, וכך מתמתנת תופעת 'אי החום העירוני'. יתרה מזאת, עצים וקרקע סופגים מי גשם כבדים, ומקלים על העומס על מערכות הניקוז העירוניות בזמן סערות קשות." },
  { en:"Equally significant is the psychological benefit: spending even twenty minutes walking among trees lowers stress hormones, restores attention fatigue, and encourages peaceful community interaction, demonstrating that thoughtful integration of nature is essential to sustainable urban design.", he:"חשובה באותה מידה התועלת הפסיכולוגית: אפילו עשרים דקות של הליכה בין עצים מורידות את רמת הורמוני הלחץ, משקמות את עייפות הקשב ומעודדות מפגש קהילתי שליו – מה שמוכיח ששילוב מחושב של טבע הוא חיוני לתכנון עירוני בר-קיימא." } ]},
 { id:"n3_aviation_safety", level:3, cover:"✈️", title:"Lessons from Aviation Safety", he:"לקחים מבטיחות הטיסה", blurb:"מה בתי חולים וחברות הנדסה למדו מהטייסים על טעויות.", paras:[
  { en:"Modern commercial aviation is widely regarded as one of the safest modes of transportation ever created, a record achieved not by assuming human perfection, but by designing systems that anticipate and catch human error.", he:"התעופה האזרחית המודרנית נחשבת לאחד מאמצעי התחבורה הבטוחים ביותר שנוצרו אי פעם – הישג שהושג לא מתוך הנחה שבני אדם מושלמים, אלא באמצעות תכנון מערכות שצופות טעויות אנוש ותופסות אותן." },
  { en:"During the mid-twentieth century, investigators realized that many aviation accidents resulted not from mechanical failure, but from communication breakdowns inside the cockpit when junior crew members hesitated to question senior captains.", he:"באמצע המאה העשרים הבינו חוקרים שתאונות טיסה רבות נבעו לא מתקלה מכנית, אלא מכשלים בתקשורת בתוך תא הטייס, כאשר אנשי צוות זוטרים היססו להטיל ספק בדברי קברניטים בכירים." },
  { en:"In response, the industry introduced Crew Resource Management, training flight crews to foster open communication, cross-check every critical instrument reading, and follow standardized written checklists regardless of experience level.", he:"בתגובה, התעשייה הנהיגה את 'ניהול משאבי צוות' (CRM), שמאמן צוותי טיסה לטפח תקשורת פתוחה, להצליב כל קריאה של מכשיר קריטי ולפעול לפי רשימות תיוג כתובות ואחידות, בלי קשר לרמת הניסיון." },
  { en:"Today, hospitals, engineering firms, and high-reliability organizations worldwide have adopted aviation's transparent 'no-blame' reporting culture, proving that analyzing small mistakes openly is the surest way to prevent major failures.", he:"כיום, בתי חולים, חברות הנדסה וארגונים בעלי אמינות גבוהה ברחבי העולם אימצו את תרבות הדיווח השקופה של התעופה, 'ללא האשמה', ומוכיחים שניתוח גלוי של טעויות קטנות הוא הדרך הבטוחה ביותר למנוע כשלים גדולים." } ]},
 { id:"n3_artisan_bread", level:3, cover:"🍞", title:"The Revival of Artisan Breadmaking", he:"תחיית אפיית הלחם המסורתית", blurb:"למה לחם שמחכים לו יום שלם טעים ובריא יותר.", paras:[
  { en:"For decades, industrial bakeries prioritized speed and shelf life, using commercial yeast and chemical additives to produce uniform loaves in under two hours. In recent years, however, a quiet culinary revival has brought renewed appreciation for traditional slow-fermented sourdough baking.", he:"במשך עשרות שנים העדיפו מאפיות תעשייתיות מהירות וחיי מדף ארוכים, והשתמשו בשמרים מסחריים ובתוספים כימיים כדי לייצר כיכרות אחידות בתוך פחות משעתיים. אולם בשנים האחרונות, תחייה קולינרית שקטה הביאה להערכה מחודשת לאפייה המסורתית של לחם מחמצת בהתססה איטית." },
  { en:"Unlike commercial yeast, a sourdough starter relies on a natural symbiotic culture of wild yeasts and beneficial bacteria thriving in flour and water. When given twelve to twenty-four hours to ferment slowly at cool temperatures, these natural microorganisms break down complex starches and proteins into simpler, more digestible nutrients while developing deep, nuanced flavors without any artificial ingredients.", he:"בניגוד לשמרים מסחריים, מחמצת מתבססת על תרבית סימביוטית טבעית של שמרי בר וחיידקים מועילים שמשגשגים בקמח ובמים. כאשר נותנים להם שתים-עשרה עד עשרים וארבע שעות לתסוס לאט בטמפרטורות קרירות, המיקרואורגניזמים הטבעיים האלה מפרקים עמילנים וחלבונים מורכבים לחומרי מזון פשוטים וקלים יותר לעיכול, ובמקביל מפתחים טעמים עמוקים ומורכבים בלי שום רכיבים מלאכותיים." },
  { en:"This return to patience illustrates how slowing down traditional food preparation often yields superior nutrition alongside richer craftsmanship.", he:"החזרה הזו לסבלנות ממחישה כיצד האטה בהכנת מזון מסורתית מניבה לעיתים קרובות תזונה טובה יותר לצד אומנות עשירה יותר." } ]},
 { id:"n3_fusion_energy", level:3, cover:"☀️", title:"The Frontier of Clean Fusion Energy", he:"החזית של אנרגיית היתוך נקייה", blurb:"המרוץ להדליק שמש קטנה כאן על כדור הארץ.", paras:[
  { en:"For over seventy years, physicists and engineers have pursued one of science's grandest ambitions: replicating the process that powers the sun and stars to generate clean, virtually limitless electricity on Earth.", he:"במשך יותר משבעים שנה רודפים פיזיקאים ומהנדסים אחר אחת השאיפות הגדולות ביותר של המדע: לשחזר את התהליך שמניע את השמש והכוכבים כדי לייצר חשמל נקי וכמעט בלתי מוגבל על פני כדור הארץ." },
  { en:"Unlike conventional nuclear fission, which splits heavy uranium atoms and produces long-lived radioactive waste, nuclear fusion merges light hydrogen isotopes—such as deuterium extracted from seawater—at temperatures exceeding one hundred million degrees Celsius.", he:"בניגוד לביקוע גרעיני רגיל, שמפצל אטומי אורניום כבדים ומייצר פסולת רדיואקטיבית ארוכת חיים, היתוך גרעיני ממזג איזוטופים קלים של מימן – כמו דאוטריום המופק ממי ים – בטמפרטורות העולות על מאה מיליון מעלות צלזיוס." },
  { en:"At such extreme heat, gas transforms into electrically charged plasma that must be suspended away from reactor walls using powerful superconducting magnets or intense laser beams.", he:"בחום קיצוני כזה, הגז הופך לפלזמה טעונה חשמלית, שיש להחזיק אותה הרחק מדפנות הכור בעזרת מגנטים על-מוליכים רבי עוצמה או קרני לייזר עזות." },
  { en:"Following recent milestone experiments in which fusion reactions successfully produced more energy than the lasers delivered to the fuel target, researchers are moving closer to turning stellar physics into a practical, sustainable energy source for future generations.", he:"בעקבות ניסויים פורצי דרך שנערכו לאחרונה, שבהם תגובות היתוך הצליחו להפיק יותר אנרגיה ממה שהלייזרים העבירו אל מטרת הדלק, החוקרים מתקרבים להפיכת הפיזיקה של הכוכבים למקור אנרגיה מעשי ובר-קיימא לדורות הבאים." } ]}
];
NEW_STORIES.forEach(s=>{ s.tags=['חדש']; });

STORIES.push(...NEW_STORIES);
